package local.proskurnin.preview;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.*;import android.graphics.*;import android.graphics.drawable.*;import android.view.*;import android.widget.*;import android.speech.RecognizerIntent;import java.util.*;import org.json.*;
public class MovieActivity extends VoiceActivity {
 LinearLayout root,cards;Button search;volatile int generation=0;android.content.SharedPreferences prefs;
 static final String[] CINEMAS={"Кинопоиск","Иви","ОККО","Премьер","Zona","LazyMedia Deluxe","Кион"};
 static final String[] PACKAGES={"ru.kinopoisk.tv","ru.ivi.client","tv.okko.androidtv","","mobi.zona","com.lazycatsoftware.lmd",""};
 public void onCreate(Bundle bundle){super.onCreate(bundle);prefs=getSharedPreferences("preview",0);if(!prefs.getBoolean("ai_enabled",true)){finish();return;}
  root=base("Что посмотрим?","КИНО · ПОДБОР ПО НАСТРОЕНИЮ");addInput(root,"Опишите настроение, жанр или сюжет…");
  voiceButton=button("◉  Голос");search=button("Подобрать");Button providers=button("Кинотеатры"),back=button("Назад");addActions(root,voiceButton,search,providers,back);
  voiceButton.setOnClickListener(v->voice());search.setOnClickListener(v->submit());providers.setOnClickListener(v->chooseProviders());back.setOnClickListener(v->finish());
  status.setText("Скажите, что хочется посмотреть. Я предложу три фильма.");
  cards=new LinearLayout(this);cards.setOrientation(0);root.addView(cards,new LinearLayout.LayoutParams(-1,0,1));showEmpty();
  TextView foot=label("Метаданные: TMDB · Наличие и озвучка зависят от выбранного кинотеатра",11);foot.setTextColor(0xff71839c);foot.setPadding(0,dp(10),0,0);root.addView(foot);voiceButton.requestFocus();
 }
 void showEmpty(){cards.removeAllViews();String[] tags={"ЛЕГКО И УЮТНО","СЮЖЕТ С ИНТРИГОЙ","ДЛЯ ВСЕЙ СЕМЬИ"};String[] prompts={"Добрая комедия до ста минут","Детектив без жестокости","Приключения, не мультфильм"};for(int i=0;i<3;i++){final String prompt=prompts[i];LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setGravity(Gravity.CENTER_VERTICAL);box.setPadding(dp(22),dp(18),dp(22),dp(18));box.setBackground(focusBackground());box.setFocusable(true);box.setClickable(true);box.setContentDescription(prompt);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-1,1);if(i>0)lp.leftMargin=dp(12);cards.addView(box,lp);TextView tag=label(tags[i],11);tag.setTextColor(0xff94a9c5);box.addView(tag);TextView text=label(prompt,24);text.setTypeface(Typeface.create("sans-serif-light",0));text.setPadding(0,dp(18),0,dp(24));box.addView(text);TextView hint=label("OK — подобрать",13);hint.setTextColor(0xff8598b3);box.addView(hint);box.setOnClickListener(v->{input.setText(prompt);submit();});}}
 void chooseProviders(){boolean[] selected=new boolean[CINEMAS.length];for(int i=0;i<selected.length;i++)selected[i]=prefs.getBoolean("cinema_"+i,true);new AlertDialog.Builder(this).setTitle("Мои кинотеатры").setMultiChoiceItems(CINEMAS,selected,(d,i,on)->selected[i]=on).setPositiveButton("Сохранить",(d,i)->{android.content.SharedPreferences.Editor e=prefs.edit();for(int j=0;j<selected.length;j++)e.putBoolean("cinema_"+j,selected[j]);e.apply();}).setNegativeButton("Отмена",null).show();}
 String cacheKey(String query){return "movie_cache_"+Integer.toHexString(query.hashCode());}
 void submit(){if(busy)return;if(listening)stopVoice();final String query=input.getText().toString().trim();if(query.length()<3||query.length()>400){status.setText("Введите запрос от 3 до 400 символов");return;}final int token=++generation;busy=true;search.setAlpha(0.5f);cards.removeAllViews();status.setText("Запрос: «"+query+"» · подбираем и проверяем фильмы…");
  new Thread(()->{JSONArray found=null;String error=null;try{
   String key=cacheKey(query);long age=System.currentTimeMillis()-prefs.getLong(key+"_at",0);
   if(query.equals(prefs.getString(key+"_query",""))&&age>=0&&age<86400000)found=new JSONArray(prefs.getString(key,"[]"));
   else{JSONObject proposal=ApiClient.request(this,"ai/movies",new JSONObject().put("query",query));if(alive&&token==generation)found=MovieClient.enrich(this,proposal,()->alive&&token==generation);if(found!=null&&found.length()>0){android.content.SharedPreferences.Editor e=prefs.edit();for(String old:prefs.getAll().keySet())if(old.startsWith("movie_cache_"))e.remove(old);e.putString(key,found.toString()).putString(key+"_query",query).putLong(key+"_at",System.currentTimeMillis()).apply();}}
  }catch(Exception e){error=ApiClient.message(e);}final JSONArray result=found;final String message=error;handler.post(()->{if(!alive||token!=generation)return;busy=false;search.setAlpha(1f);if(message!=null){status.setText(message);return;}if(result==null||result.length()==0){status.setText("Не нашлось фильмов, прошедших проверку ограничений. Попробуйте изменить запрос.");return;}status.setText("Запрос: «"+query+"»"+(result.length()<3?" · найдено "+result.length()+" подходящих фильма":""));showCards(result,token);});},"movie-picker").start();
 }
 void showCards(JSONArray movies,int token){for(int i=0;i<Math.min(3,movies.length());i++){try{JSONObject movie=movies.getJSONObject(i);LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setPadding(dp(12),dp(12),dp(12),dp(12));card.setBackground(focusBackground());card.setFocusable(true);card.setClickable(true);card.setContentDescription(movie.getString("title")+". OK — выбрать кинотеатр");LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-1,1);if(i>0)lp.leftMargin=dp(12);cards.addView(card,lp);
   LinearLayout hero=new LinearLayout(this);hero.setGravity(Gravity.CENTER_VERTICAL);card.addView(hero,new LinearLayout.LayoutParams(-1,0,1));
   ImageView poster=new ImageView(this);poster.setScaleType(ImageView.ScaleType.FIT_CENTER);hero.addView(poster,new LinearLayout.LayoutParams(dp(98),-1));
   LinearLayout info=new LinearLayout(this);info.setOrientation(1);info.setGravity(Gravity.CENTER_VERTICAL);info.setPadding(dp(14),0,0,0);hero.addView(info,new LinearLayout.LayoutParams(0,-1,1));TextView title=label(movie.getString("title"),22);title.setMaxLines(4);title.setEllipsize(android.text.TextUtils.TruncateAt.END);info.addView(title);
   TextView meta=label(movie.optString("year")+"  ·  "+movie.optInt("runtime")+" мин",12);meta.setTextColor(0xffa5b4c9);meta.setPadding(0,dp(12),0,dp(10));info.addView(meta);TextView rating=label("★ "+String.format(Locale.US,"%.1f",movie.optDouble("rating")),16);rating.setTextColor(0xffe7d6aa);info.addView(rating);
   TextView reason=label(movie.getString("reason"),14);reason.setTextColor(0xffb5c2d5);reason.setMaxLines(3);reason.setEllipsize(android.text.TextUtils.TruncateAt.END);LinearLayout.LayoutParams why=new LinearLayout.LayoutParams(-1,dp(66));why.topMargin=dp(8);card.addView(reason,why);TextView hint=label("OK  ·  Выбрать кинотеатр",12);hint.setTextColor(0xff9ab7df);card.addView(hint);card.setOnClickListener(v->openCinema(movie.optString("title")));card.setNextFocusUpId(voiceButton.getId());if(i==0)card.requestFocus();
   new Thread(()->{Bitmap image=null;try{image=MovieClient.poster(this,movie.optString("poster_path"));}catch(Exception ignored){}final Bitmap ready=image;handler.post(()->{if(alive&&token==generation)poster.setImageBitmap(ready);else if(ready!=null)ready.recycle();});},"movie-poster").start();
  }catch(Exception ignored){}}
 }
 String installedCinema(int index){String expected=PACKAGES[index];if(!expected.isEmpty()&&(getPackageManager().getLeanbackLaunchIntentForPackage(expected)!=null||getPackageManager().getLaunchIntentForPackage(expected)!=null))return expected;
  for(ResolveInfo info:getPackageManager().queryIntentActivities(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LEANBACK_LAUNCHER),0)){String label=info.loadLabel(getPackageManager()).toString().toLowerCase(new Locale("ru"));String wanted=CINEMAS[index].toLowerCase(new Locale("ru"));if(label.equals(wanted)||(index==3&&label.contains("premier"))||(index==6&&label.contains("kion")))return info.activityInfo.packageName;}return null;}
 void openCinema(String title){ArrayList<String> labels=new ArrayList<>(),packages=new ArrayList<>();for(int i=0;i<CINEMAS.length;i++)if(prefs.getBoolean("cinema_"+i,true)){String pkg=installedCinema(i);if(pkg!=null){labels.add(CINEMAS[i]);packages.add(pkg);}}
  if(labels.isEmpty()){Toast.makeText(this,"Выбранные кинотеатры не установлены",Toast.LENGTH_LONG).show();return;}
  new AlertDialog.Builder(this).setTitle("Где искать «"+title+"»?").setItems(labels.toArray(new String[0]),(d,n)->{Intent intent=getPackageManager().getLeanbackLaunchIntentForPackage(packages.get(n));if(intent==null)intent=getPackageManager().getLaunchIntentForPackage(packages.get(n));try{if(intent!=null)startActivity(intent);else throw new ActivityNotFoundException();}catch(Exception e){Toast.makeText(this,"Не удалось открыть приложение",0).show();}}).setNegativeButton("Отмена",null).show();
 }
 public void onBackPressed(){if(!listening)generation++;super.onBackPressed();}
 protected void onDestroy(){generation++;super.onDestroy();}
}
